-- Default SLA policies per priority with L1->L2->L3 escalation tiers.
-- Seeds one shared business calendar (required: SlaEngine skips policies
-- without one), four INCIDENT policies keyed on the seeded priority names
-- (Critical/High/Medium/Low), and three escalation tiers per policy wired to
-- the real support-tier teams from V38 (L1=...0020, L2=...0021, L3=...0022).
--
-- Tier design (triggers are independent candidates — SlaBreachMonitorJob fires
-- the lowest tier above the current level whose trigger is met):
--   level 1: ON_STUCK_STATUS  — incident stuck in NEW for the response target
--   level 2: ON_RESPONSE_BREACH
--   level 3: ON_RESOLUTION_BREACH
-- All targets are business minutes against the seeded calendar.

-- Shared calendar: Mon-Fri 09:00-17:00 America/New_York, no holidays.
INSERT INTO business_calendar (id, org_id, name, timezone, working_hours, holidays, created_by, updated_by)
VALUES (
    '00000000-0000-0000-0000-000000000030'::uuid,
    '00000000-0000-0000-0000-000000000001'::uuid,
    'Standard Business Hours',
    'America/New_York',
    '{"monday": {"start": "09:00", "end": "17:00"}, "tuesday": {"start": "09:00", "end": "17:00"}, "wednesday": {"start": "09:00", "end": "17:00"}, "thursday": {"start": "09:00", "end": "17:00"}, "friday": {"start": "09:00", "end": "17:00"}}'::jsonb,
    '[]'::jsonb,
    '00000000-0000-0000-0000-000000000000'::uuid,
    '00000000-0000-0000-0000-000000000000'::uuid
)
ON CONFLICT (id) DO NOTHING;

-- Policies: one per seeded priority name. No null-filter catch-all —
-- findBestPolicy uses findFirst() on an unordered list, so a catch-all could
-- shadow the specific policies.
