    ('00000000-0000-0000-0000-000000000033'::uuid, '00000000-0000-0000-0000-000000000001'::uuid, 'SLA - Medium',   'INCIDENT', 'Medium',   240, 1440, '00000000-0000-0000-0000-000000000030'::uuid, '00000000-0000-0000-0000-000000000000'::uuid, '00000000-0000-0000-0000-000000000000'::uuid),
    ('00000000-0000-0000-0000-000000000034'::uuid, '00000000-0000-0000-0000-000000000001'::uuid, 'SLA - Low',      'INCIDENT', 'Low',      480, 4320, '00000000-0000-0000-0000-000000000030'::uuid, '00000000-0000-0000-0000-000000000000'::uuid, '00000000-0000-0000-0000-000000000000'::uuid)
ON CONFLICT (id) DO NOTHING;

